    @TargetAggregateIdentifier var fXTradeId: UUID? = null,
    var tradeReference: String? = null,
    var tradeDate:  Date? = null,
    var settlementDate:  Date? = null,
         @AttributeOverrides(
      AttributeOverride( name = "amount", column = Column(name = "amountSold_amount")),
      AttributeOverride( name = "currency", column = Column(name = "amountSold_currency"))
    )
    var amountSold: Money? = null,
         @AttributeOverrides(
      AttributeOverride( name = "amount", column = Column(name = "amountBought_amount")),
      AttributeOverride( name = "currency", column = Column(name = "amountBought_currency"))
    )
    var amountBought: Money? = null,
    var rate: java.math.BigDecimal? = null,
    @Enumerated(EnumType.STRING) var status: TradeStatus? = null
)

data class UpdateFXTradeCommand(
    @TargetAggregateIdentifier var fXTradeId: UUID? = null,
    var tradeReference: String? = null,
    var tradeDate:  Date? = null,
    var settlementDate:  Date? = null,
         @AttributeOverrides(
      AttributeOverride( name = "amount", column = Column(name = "amountSold_amount")),
      AttributeOverride( name = "currency", column = Column(name = "amountSold_currency"))
    )
    var amountSold: Money? = null,
         @AttributeOverrides(
      AttributeOverride( name = "amount", column = Column(name = "amountBought_amount")),
      AttributeOverride( name = "currency", column = Column(name = "amountBought_currency"))
    )
    var amountBought: Money? = null,
    var rate: java.math.BigDecimal? = null,
    var customer: Customer? = null,
    var bank: Bank? = null,
    var exchangeRate: ExchangeRate? = null,
    var sourceAccount: Account? = null,
    var destinationAccount: Account? = null,
    var transaction: Transaction? = null,
    @Enumerated(EnumType.STRING) var status: TradeStatus? = null
)

data class DeleteFXTradeCommand(@TargetAggregateIdentifier  var id: UUID? = null)

// single association commands
data class AssignCustomerToFXTradeCommand(@TargetAggregateIdentifier  val parentId: UUID, val childId: UUID )
data class UnAssignCustomerFromFXTradeCommand(@TargetAggregateIdentifier  val parentId: UUID, val childId: UUID )
data class AssignBankToFXTradeCommand(@TargetAggregateIdentifier  val parentId: UUID, val childId: UUID )
data class UnAssignBankFromFXTradeCommand(@TargetAggregateIdentifier  val parentId: UUID, val childId: UUID )
