data class UnAssignExchangeRateFromFXTradeCommand(@TargetAggregateIdentifier  val parentId: UUID, val childId: UUID )
data class AssignSourceAccountToFXTradeCommand(@TargetAggregateIdentifier  val parentId: UUID, val childId: UUID )
data class UnAssignSourceAccountFromFXTradeCommand(@TargetAggregateIdentifier  val parentId: UUID, val childId: UUID )
data class AssignDestinationAccountToFXTradeCommand(@TargetAggregateIdentifier  val parentId: UUID, val childId: UUID )
data class UnAssignDestinationAccountFromFXTradeCommand(@TargetAggregateIdentifier  val parentId: UUID, val childId: UUID )
data class AssignTransactionToFXTradeCommand(@TargetAggregateIdentifier  val parentId: UUID, val childId: UUID )
data class UnAssignTransactionFromFXTradeCommand(@TargetAggregateIdentifier  val parentId: UUID, val childId: UUID )

